function normalize(s) {
  return (s ?? '').toString().toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .trim();
}
function splitList(v) {
  if (!v) return [];
  const str = String(v).trim();
  if (str.startsWith('[') && str.endsWith(']')) {
    try { const p = JSON.parse(str); if (Array.isArray(p)) return p.map(s => String(s).trim()).filter(Boolean); } catch (e) {}
  }
  return str.split(/[,;|]+/).map(s => s.trim()).filter(Boolean);
}
function splitListConY(v) {
  if (!v) return [];
  const str = String(v).trim();
  if (str.startsWith('[') && str.endsWith(']')) {
    try { const p = JSON.parse(str); if (Array.isArray(p)) return p.map(s => String(s).trim()).filter(Boolean); } catch (e) {}
  }
  return str.split(/[,;|]+|\s+y\s+/i).map(s => s.trim()).filter(Boolean);
}
function parseBool(v) {
  const s = normalize(v);
  if (s === 'TRUE' || s === '1' || s === 'SI' || s === 'S' || s === 'YES') return true;
  if (s === 'FALSE' || s === '0' || s === 'NO' || s === 'N') return false;
  return null;
}
const MUNICIPIOS_POR_CATEGORIA = {
  'BARRANQUILLA': ['Barranquilla'],
  'AREA METROPOLITANA DE BARRANQUILLA': ['Barranquilla', 'Soledad', 'Malambo', 'Galapa', 'Puerto Colombia'],
  'TODO EL DEPARTAMENTO DEL ATLANTICO': ['Barranquilla', 'Soledad', 'Malambo', 'Galapa', 'Puerto Colombia', 'Sabanagrande', 'Santo Tomas', 'Palmar de Varela', 'Ponedera', 'Campo de la Cruz', 'Suan', 'Candelaria', 'Manati', 'Repelon', 'Luruaco', 'Sabanalarga', 'Usiacuri', 'Piojo', 'Juan de Acosta', 'Tubara', 'Baranoa', 'Cerro de San Antonio', 'Concordia', 'Pedraza', 'Remolino', 'Sitionuevo', 'Zapayan']
};
const TAMANO_FORM_TO_BD = {
  'MICROEMPRESAS': 'MICRO',
  'PEQUENAS EMPRESAS': 'PEQUENA',
  'MEDIANAS EMPRESAS': 'MEDIANA',
  'GRANDES EMPRESAS': 'GRANDE'
};
// El form ofrece 'Personas Juridicas'/'Personas Naturales' (plural); la BD guarda
// 'PERSONA JURIDICA'/'PERSONA NATURAL' (singular). Sin este mapeo, Array.includes()
// nunca matchea y CUALQUIER solicitud real da 0 empresas encontradas siempre.
const TIPO_FORM_TO_BD = {
  'PERSONAS JURIDICAS': 'PERSONA JURIDICA',
  'PERSONAS NATURALES': 'PERSONA NATURAL',
  'ESTABLECIMIENTOS': 'PERSONA JURIDICA',
  'ENTIDADES SIN ANIMO DE LUCRO': 'PERSONA JURIDICA'
};

const row = $json;
const tipoRaw = splitListConY(row.tipo_organizacion);
const tipoNorm = tipoRaw.map(normalize).map(t => TIPO_FORM_TO_BD[t] || t);
const municipioCategoria = MUNICIPIOS_POR_CATEGORIA[normalize(row.municipios)];
const municipiosRaw = municipioCategoria || splitListConY(row.municipios);
const municipiosNorm = municipiosRaw.map(normalize);
const sectoresRaw = splitList(row.sectores);
const esTodosSectores = sectoresRaw.some(s => /TOD[AO]S?/.test(normalize(s)));
const sectoresNorm = (esTodosSectores || !sectoresRaw.length) ? null : sectoresRaw.map(normalize);
const criterioSector = (esTodosSectores || !sectoresRaw.length) ? 'Todas las actividades economicas' : sectoresRaw.join(', ');
const tamanoRaw = splitList(row.tamano_empresa).map(normalize);
const esTodosTamano = tamanoRaw.some(s => /TOD[AO]S?/.test(s));
const tamanoNorm = (esTodosTamano || !tamanoRaw.length) ? null : tamanoRaw.map(t => TAMANO_FORM_TO_BD[t] || t);
const num = (v) => (v === null || v === undefined || v === '') ? null : Number(v);

return {
  json: {
    id_solicitud: row.id_solicitud,
    _tipoNorm: tipoNorm,
    _municipiosNorm: (municipiosRaw.length ? municipiosNorm : null),
    _sectoresNorm: sectoresNorm,
    _tamanoNorm: tamanoNorm,
    _activosMin: num(row.activos_min),
    _activosMax: num(row.activos_max),
    _activosEntre: num(row.activos_entre),
    _activosY: num(row.activos_y),
    _ventasMin: num(row.ventas_min),
    _ventasMax: num(row.ventas_max),
    _ventasEntre: num(row.ventas_entre),
    _ventasY: num(row.ventas_y),
    indiferente_ventas: parseBool(row.indiferente_ventas),
    CRITERIO_SECTOR: criterioSector,
    tipo_servicio: row.tipo_servicio || '',
    visitas_por_asesor: row.visitas_por_asesor ?? null,
    incluye_rutas: row.incluye_rutas ?? null,
    num_niveles: row.num_niveles ?? null,
    total_registros: row.total_registros ?? null,
    plan_deseado: row.plan_deseado ?? null,
    ya_sabe_plan: row.ya_sabe_plan ?? null,
    consultas_mensuales: row.consultas_mensuales ?? null,
    numero_usuarios: row.numero_usuarios ?? null,
    servicio: row.servicio,
    nombre_solicitante: row.nombre_solicitante,
    razon_social: row.razon_social,
    email_solicitante: row.email_solicitante,
    telefono_solicitante: row.telefono_solicitante,
    ciudad: row.ciudad,
    organizacion_juridica: row.organizacion_juridica,
    ubicacion_geografica: row.ubicacion_geografica,
    actividad_economica: row.actividad_economica,
    tipo_base: row.tipo_base,
    cantidad_registros: row.cantidad_registros,
    visitas_asesor: row.visitas_asesor,
    incluir_rutas: row.incluir_rutas,
    niveles_analisis: row.niveles_analisis,
    plan_en_linea: row.plan_en_linea,
    consultas_mensuales: row.consultas_mensuales,
    usuarios: row.usuarios
  }
};

function normalize(s) {
  return (s ?? '').toString().toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
}
function lookupTarifa(n) {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error('lookupTarifa recibio un conteo invalido (' + n + '): debe ser un entero positivo.');
  }
  const TARIFAS = [
    { min: 1, max: 50, valor: 149700 }, { min: 51, max: 150, valor: 258200 },
    { min: 151, max: 300, valor: 366300 }, { min: 301, max: 500, valor: 568600 },
    { min: 501, max: 700, valor: 709000 }, { min: 701, max: 900, valor: 799500 },
    { min: 901, max: 1200, valor: 978400 }, { min: 1201, max: 2400, valor: 1264500 },
    { min: 2401, max: 4800, valor: 1993500 }, { min: 4801, max: 9600, valor: 3109700 },
    { min: 9601, max: 100000, valor: 13059500 }
  ];
  const t = TARIFAS.find(x => n >= x.min && n <= x.max);
  return t ? t.valor : TARIFAS[TARIFAS.length - 1].valor;
}
const SECTOR_PREFIX = {
  'AGROPECUARIO': 'AG', 'ALOJAMIENTO Y RESTAURANTES': 'AL',
  'ARTISTICAS, DE ENTRETENIMIENTO Y RECREACION': 'AR',
  'COMERCIO AL POR MAYOR Y AL POR MENOR': 'CO', 'CONSTRUCCION': 'CN', 'EDUCACION': 'ED',
  'ELECTRICIDAD, GAS, VAPOR Y AIRE ACONDICIONADO': 'EL', 'FINANCIERO Y SEGUROS': 'FI',
  'INDUSTRIA': 'IN', 'INFORMACION Y COMUNICACIONES': 'IC', 'INMOBILIARIAS': 'IM', 'MINERO': 'MI',
  'OTRAS ACTIVIDADES DE SERVICIOS': 'OT', 'PROFESIONALES, CIENTIFICAS Y TECNICAS': 'PR',
  'SALUD Y ASISTENCIA SOCIAL': 'SA', 'SERVICIOS ADMINISTRATIVOS Y DE APOYO': 'SE',
  'SUMINISTROS Y EVACUACIÓN DE AGUA, DESECHOS': 'SU', 'TRANSPORTE': 'TR'
};
const TAMANO_SUFFIX = { 'Micro': '_Mi', 'Pequena': '_P', 'Mediana': '_M', 'Grande': '_G' };
const TIPO_PREFIX = { 'PERSONA JURIDICA': 'PJ', 'PERSONA NATURAL': 'PN' };
const SECTORES_SIN_REGISTRO_MERCANTIL = ['ADMINISTRACION PUBLICA', 'HOGARES INDIVIDUALES', 'EXTRATERRITORIALES'];

function resolverSectorCanonico(tokenNorm) {
  if (!tokenNorm) return null;
  const canonicos = Object.keys(SECTOR_PREFIX);
  const exacto = canonicos.find(canon => normalize(canon) === tokenNorm);
  if (exacto) return normalize(exacto);
  const candidatos = canonicos.filter(canon => {
    const canonNorm = normalize(canon);
    return canonNorm.includes(tokenNorm) || tokenNorm.includes(canonNorm);
  });
  if (candidatos.length === 1) return normalize(candidatos[0]);
  if (candidatos.length > 1) return { ambiguo: candidatos };
  return null;
}

function parseBool(v) {
  const s = normalize(v);
  if (s === 'TRUE' || s === '1' || s === 'SI' || s === 'S' || s === 'YES') return true;
  if (s === 'FALSE' || s === '0' || s === 'NO' || s === 'N') return false;
  return null;
}

function col(row, name) {
  if (row[name] !== undefined) return row[name];
  if (row[name + '.'] !== undefined) return row[name + '.'];
  const trimmedKey = Object.keys(row).find(k => k.replace(/\.$/, '') === name);
  return trimmedKey ? row[trimmedKey] : undefined;
}

const nf = (n) => (n === null || n === undefined || n === '' || isNaN(Number(n))) ? '' : Number(n).toLocaleString('es-CO');
const fmt = (n) => (n === null || n === undefined || n === '' || isNaN(Number(n))) ? '' : '$ ' + Number(n).toLocaleString('es-CO');

const ASESOR_NOMBRE = (($('Ejecutar Leer Configuración').first().json._config || {}).asesor_nombre || '');
const ASESOR_EMAIL = (($('Ejecutar Leer Configuración').first().json._config || {}).asesor_email || '');
const ASESOR_TELEFONO = (($('Ejecutar Leer Configuración').first().json._config || {}).asesor_telefono || '');
const numeroPropuesta = 'SOL-' + DateTime.now().setZone('America/Bogota').toFormat('yyyyMMddHHmmss');
const fechaPropuesta = DateTime.now().setZone('America/Bogota').toFormat('dd/MM/yyyy');
const DATOS_FIJOS = {
  numero_propuesta: numeroPropuesta,
  fecha_propuesta: fechaPropuesta,
  asesor_nombre: ASESOR_NOMBRE,
  asesor_email: ASESOR_EMAIL,
  asesor_telefono: ASESOR_TELEFONO
};
for (const codigo of ['AP', 'HO', 'EX']) {
  for (const suf of ['_G', '_M', '_P', '_Mi', '_T']) {
    DATOS_FIJOS['PJ_' + codigo + suf] = 0;
    DATOS_FIJOS['PN_' + codigo + suf] = 0;
  }
}

const criterios = $('Normalizar Criterios').first().json;
const DATOS_CLIENTE = {
  nombre_cliente: criterios.nombre_solicitante,
  email_cliente: criterios.email_solicitante,
  telefono: criterios.telefono_solicitante,
  ubicacion: criterios.ciudad
};
DATOS_FIJOS.nombre_archivo = (criterios.id_solicitud || numeroPropuesta) + '_' + (criterios.servicio || 'propuesta').replace(/[^a-zA-Z0-9_-]/g, '_');
const servicio = normalize(criterios.tipo_servicio);
if (!servicio) {
  return [{ json: { ok: false, error: 'Falta tipo_servicio.', ...DATOS_FIJOS } }];
}
const esGeo = servicio.includes('GEORREFERENCIADA') || servicio === 'GEO';
const esZonif = servicio.includes('ZONIFICACI') || servicio === 'ZONIF';
const esUbic = servicio.includes('UBICACI') || servicio === 'UBIC';
const esInfoLinea = (servicio.includes('INFORMACI') && servicio.includes('NEA')) || servicio === 'INFOLINEA';

const IVA_RATE = 0.19;

if (esInfoLinea) {
  const PLANES = [
    { nombre: 'Bronce', inversionInicial: 1998000, pagoMensual: 273600, consultas: 70, usuarios: 1, valor: 5007600 },
    { nombre: 'Plata', inversionInicial: 2998200, pagoMensual: 409300, consultas: 150, usuarios: 1, valor: 7500500 },
    { nombre: 'Gold', inversionInicial: 4908900, pagoMensual: 711600, consultas: 500, usuarios: 2, valor: 12736500 },
    { nombre: 'Rubí', inversionInicial: 6984000, pagoMensual: 953000, consultas: 1000, usuarios: 3, valor: 17467000 },
    { nombre: 'Diamante', inversionInicial: 9613200, pagoMensual: 1310600, consultas: Infinity, usuarios: 5, valor: 24029800 }
  ];
  let plan = null;
  const yaSabePlan = parseBool(criterios.ya_sabe_plan);
  const planDeseado = (criterios.plan_deseado || '').toString().trim();
  const planDeseadoNorm = normalize(planDeseado).replace(/^PLAN\s+/, '');
  if (yaSabePlan && planDeseado) {
    plan = PLANES.find(p => normalize(p.nombre) === planDeseadoNorm);
    if (!plan) {
      return [{ json: { ok: false, error: 'El plan "' + planDeseado + '" no coincide con ninguno de los 5 planes (Bronce/Plata/Gold/Rubí/Diamante).', ...DATOS_FIJOS } }];
    }
  } else {
    const consultasProvista = criterios.consultas_mensuales !== null && criterios.consultas_mensuales !== undefined && criterios.consultas_mensuales !== '';
    const usuariosProvisto = criterios.numero_usuarios !== null && criterios.numero_usuarios !== undefined && criterios.numero_usuarios !== '';
    const consultas = Number(criterios.consultas_mensuales);
    const usuarios = Number(criterios.numero_usuarios);
    if (!consultasProvista || !usuariosProvisto || !isFinite(consultas) || !isFinite(usuarios)) {
      return [{ json: { ok: false, error: 'Informacion en Linea necesita plan_deseado (con ya_sabe_plan=true) o consultas_mensuales + numero_usuarios.', ...DATOS_FIJOS } }];
    }
    plan = PLANES.find(p => consultas <= p.consultas && usuarios <= p.usuarios);
    if (!plan) {
      return [{ json: { ok: false, error: 'numero_usuarios (' + usuarios + ') excede el maximo del plan disponible (Diamante: 5). No hay un plan que cubra ese numero de usuarios.', ...DATOS_FIJOS } }];
    }
  }
  const iva = Math.round(plan.valor * IVA_RATE);
  const ilConsultasTxt = plan.consultas === Infinity ? 'Consultas ilimitadas' : (nf(plan.consultas) + ' consultas/mes');
  const ilUsuariosTxt = plan.usuarios + (plan.usuarios === 1 ? ' usuario' : ' usuarios');
  return [{ json: {
    ok: true,
    PLAN_SELECCIONADO: plan.nombre,
    INVERSION_INICIAL: plan.inversionInicial,
    PAGO_MENSUAL: plan.pagoMensual,
    VALOR: plan.valor,
    IVA: iva,
    VALOR_TOTAL: plan.valor + iva,
    VALOR_FMT: fmt(plan.valor),
    IVA_FMT: fmt(iva),
    VALOR_TOTAL_FMT: fmt(plan.valor + iva),
    IL_PLAN: plan.nombre,
    IL_INICIAL: fmt(plan.inversionInicial),
    IL_MENSUAL: fmt(plan.pagoMensual),
    IL_CONSULTAS: ilConsultasTxt,
    IL_USUARIOS: ilUsuariosTxt,
    varEntregables:
      'Acceso a la plataforma web de la CCB para consultar 1 a 1 las empresas inscritas en el registro mercantil, las 24 horas.\n' +
      'Evitar fraudes y mejorar la seguridad en sus transacciones comerciales.\n' +
      'Disponer de datos para análisis y comprobación.\n' +
      'Verificación de datos de proveedores.\n' +
      'Acceso web 24/7 a la base de datos del registro mercantil.',
    ...DATOS_FIJOS,
    ...DATOS_CLIENTE,
    ...criterios
  } }];
}

if (!esGeo && !esZonif && !esUbic) {
  return [{ json: { ok: false, error: 'tipo_servicio no reconocido ("' + criterios.tipo_servicio + '").', ...DATOS_FIJOS } }];
}

let totalRegistros;
let pivot = null;
let pivotPorTipo = null;
let filasDescartadasPivote = 0;

const tieneOverride = criterios.total_registros !== null && criterios.total_registros !== undefined && criterios.total_registros !== '';
if (tieneOverride) {
  const overrideNum = Number(criterios.total_registros);
  if (!Number.isInteger(overrideNum) || overrideNum <= 0) {
    return [{ json: { ok: false, error: 'total_registros recibido ("' + criterios.total_registros + '") no es un entero positivo valido.', ...DATOS_FIJOS } }];
  }
  totalRegistros = overrideNum;
} else {
  const tipoSel = criterios._tipoNorm;
  const municipiosSel = criterios._municipiosNorm;
  const sectoresRawNorm = criterios._sectoresNorm;
  const tamanoSel = criterios._tamanoNorm;
  const activosMin = criterios._activosMin, activosMax = criterios._activosMax, activosEntre = criterios._activosEntre, activosY = criterios._activosY;
  const ventasMin = criterios._ventasMin, ventasMax = criterios._ventasMax, ventasEntre = criterios._ventasEntre, ventasY = criterios._ventasY;
  const indifVentas = criterios.indiferente_ventas;

  if (!tipoSel || !tipoSel.length) {
    return [{ json: { ok: false, error: 'Falta tipo_organizacion -- no se puede contar sin ese dato.', ...DATOS_FIJOS } }];
  }

  let sectoresCanonicos = null;
  if (sectoresRawNorm && sectoresRawNorm.length) {
    sectoresCanonicos = [];
    for (const token of sectoresRawNorm) {
      const esSectorSinRegistro = SECTORES_SIN_REGISTRO_MERCANTIL.some(s => token.includes(s));
      if (esSectorSinRegistro) {
        continue;
      }
      const resuelto = resolverSectorCanonico(token);
      if (resuelto === null) {
        return [{ json: { ok: false, error: 'Sector "' + token + '" no coincide con ninguno de los 18 sectores economicos canonicos.', CRITERIO_SECTOR: criterios.CRITERIO_SECTOR, ...DATOS_FIJOS } }];
      }
      if (typeof resuelto === 'object') {
        return [{ json: { ok: false, error: 'Sector "' + token + '" es ambiguo -- coincide con varios canonicos (' + resuelto.ambiguo.join(' / ') + ').', CRITERIO_SECTOR: criterios.CRITERIO_SECTOR, ...DATOS_FIJOS } }];
      }
      sectoresCanonicos.push(resuelto);
    }
  }

  const bdRows = $input.all().map(it => it.json).filter(r => Object.keys(r).length > 0);
  if (bdRows.length === 0) {
    throw new Error('La lectura de la BD de empresas (hoja BD) no devolvio ninguna fila real -- probable fallo de lectura de Excel/Graph. Revisar la conexion/hoja antes de reintentar.');
  }

  const filtrado = bdRows.filter(r => {
    const tipo = normalize(col(r, 'TIPO EMP'));
    const municipio = normalize(r['NOMBRE_MUNICIPIO_DC']);
    const sector = normalize(r['SECTOR']);
    const tamano = normalize(String(r['TAMANO'] ?? '').trim());
    const activo = Number(r['TOTAL_ACTIVO']);
    const ventas = Number(r['ING_ACT_ORDI']);
    if (!tipoSel.includes(tipo)) return false;
    if (municipiosSel && municipiosSel.length && !municipiosSel.includes(municipio)) return false;
    if (sectoresCanonicos && !sectoresCanonicos.includes(sector)) return false;
    if (tamanoSel && tamanoSel.length && !tamanoSel.includes(tamano)) return false;
    if (activosEntre != null || activosMin != null) {
      const lo = activosEntre != null ? activosEntre : activosMin;
      if (!(isFinite(activo) && activo >= lo)) return false;
    }
    if (activosY != null || activosMax != null) {
      const hi = activosY != null ? activosY : activosMax;
      if (!(isFinite(activo) && activo <= hi)) return false;
    }
    if (indifVentas !== true) {
      if (ventasEntre != null || ventasMin != null) {
        const lo = ventasEntre != null ? ventasEntre : ventasMin;
        if (!(isFinite(ventas) && ventas >= lo)) return false;
      }
      if (ventasY != null || ventasMax != null) {
        const hi = ventasY != null ? ventasY : ventasMax;
        if (!(isFinite(ventas) && ventas <= hi)) return false;
      }
    }
    return true;
  });

  totalRegistros = filtrado.length;
  if (totalRegistros === 0) {
    return [{ json: { ok: false, error: 'No se encontraron empresas que cumplan esos criterios (0 registros).', CRITERIO_SECTOR: criterios.CRITERIO_SECTOR, ...DATOS_FIJOS } }];
  }

  pivot = {};
  for (const sectorFull of Object.keys(SECTOR_PREFIX)) {
    const prefix = SECTOR_PREFIX[sectorFull];
    for (const suf of Object.values(TAMANO_SUFFIX)) pivot[prefix + suf] = 0;
    pivot[prefix + '_T'] = 0;
  }
  for (const suf of Object.values(TAMANO_SUFFIX)) pivot['TOT' + suf] = 0;
  pivot['TOT_T'] = 0;

  pivotPorTipo = { PJ: {}, PN: {} };
  for (const tp of Object.keys(pivotPorTipo)) {
    for (const sectorFull of Object.keys(SECTOR_PREFIX)) {
      const prefix = SECTOR_PREFIX[sectorFull];
      for (const suf of Object.values(TAMANO_SUFFIX)) pivotPorTipo[tp][prefix + suf] = 0;
      pivotPorTipo[tp][prefix + '_T'] = 0;
    }
    for (const suf of Object.values(TAMANO_SUFFIX)) pivotPorTipo[tp]['TOT' + suf] = 0;
    pivotPorTipo[tp]['TOT_T'] = 0;
  }

  for (const row of filtrado) {
    const sectorNorm = normalize(row['SECTOR']);
    const sectorFull = Object.keys(SECTOR_PREFIX).find(s => normalize(s) === sectorNorm);
    if (!sectorFull) { filasDescartadasPivote++; continue; }
    const prefix = SECTOR_PREFIX[sectorFull];
    const tamanoRaw = String(row['TAMANO'] ?? '').trim();
    const sufKey = Object.keys(TAMANO_SUFFIX).find(k => normalize(k) === normalize(tamanoRaw));
    const suf = sufKey ? TAMANO_SUFFIX[sufKey] : null;
    if (!suf) { filasDescartadasPivote++; continue; }
    pivot[prefix + suf] += 1;
    pivot[prefix + '_T'] += 1;
    pivot['TOT' + suf] += 1;
    pivot['TOT_T'] += 1;

    const tipoNorm = normalize(col(row, 'TIPO EMP'));
    const tipoKey = TIPO_PREFIX[tipoNorm];
    if (tipoKey) {
      pivotPorTipo[tipoKey][prefix + suf] += 1;
      pivotPorTipo[tipoKey][prefix + '_T'] += 1;
      pivotPorTipo[tipoKey]['TOT' + suf] += 1;
      pivotPorTipo[tipoKey]['TOT_T'] += 1;
    }
  }
}

const TARIFA_ZONA = 281700;
const TARIFA_RUTA = 205100;
const TARIFA_MAPA = 80500;
const TARIFA_NIVEL = 511300;
const MAX_ZONAS_O_NIVELES_RAZONABLE = 200;

const valorBaseDatos = lookupTarifa(totalRegistros);
let valor = valorBaseDatos;
const extras = {};
let camposServicio = {};

if (esZonif) {
  const visitas = Number(criterios.visitas_por_asesor);
  if (!criterios.visitas_por_asesor || !isFinite(visitas) || visitas <= 0) {
    return [{ json: { ok: false, error: 'Zonificacion y Rutero necesita visitas_por_asesor (> 0).', ...DATOS_FIJOS } }];
  }
  const incluyeRutas = parseBool(criterios.incluye_rutas);
  if (incluyeRutas === null) {
    return [{ json: { ok: false, error: 'incluye_rutas ambiguo o ausente ("' + criterios.incluye_rutas + '").', ...DATOS_FIJOS } }];
  }
  const numZonas = Math.max(1, Math.ceil(totalRegistros / visitas));
  if (numZonas > MAX_ZONAS_O_NIVELES_RAZONABLE) {
